import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:negative @smoke Rejects malformed email in contact form', async ({ page }) => {
  await opGoto(page, '/contact')
  await opClick(page, 'combobox', 'Which service are you interested in')
  await opClick(page, 'option', 'Test Automation')
  await opFill(page, 'Name', 'Alex Johnson')
  await opFill(page, 'Email', 'not-an-email')
  await opFill(page, 'Message', 'We need a test automation audit for our fintech platform.')
  await opClick(page, 'button', 'Send')
  await opSeen(page, 'alert', 'Please enter a valid email address.')
})
